# 文件职责：以示范、新任务对话和反馈为主入口；所有示范/模型文本均安全展示。
PAGE = r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Autodidact · 示范学习</title>
<style>
:root{font-family:Segoe UI,Microsoft YaHei,sans-serif;color:#203347;background:#f3f6fa}*{box-sizing:border-box}body{margin:0}header{padding:19px 26px;background:#162a40;color:white;display:flex;justify-content:space-between;align-items:center;gap:15px}header h1{margin:0 0 6px;font-size:22px}header p{margin:0;color:#c3d2e3;font-size:13px}nav{display:flex;gap:12px;align-items:center}a{color:#225db1}header a{color:#d2e1f4;font-size:13px}button{font:inherit;font-size:13px;padding:9px 13px;border:1px solid #c9d6e5;border-radius:7px;background:white;color:#20384e;cursor:pointer}button.primary{background:#2362d4;color:white;border-color:#2362d4}button.good{background:#eaf6ed;color:#25673b;border-color:#b8d9bf}button:disabled{opacity:.45;cursor:default}main{display:grid;grid-template-columns:265px minmax(420px,1fr) 290px;gap:18px;padding:20px;max-width:1700px;margin:auto}.card{background:white;border:1px solid #e0e7ef;border-radius:12px;padding:17px;margin-bottom:16px}h2{font-size:16px;margin:0 0 12px}h3{font-size:14px;margin:8px 0}.muted,label{font-size:12px;color:#65768c;line-height:1.7}input,textarea{font:inherit;width:100%;border:1px solid #cbd7e5;border-radius:7px;padding:10px;margin:5px 0 12px;background:white}textarea{resize:vertical}.course{display:block;width:100%;text-align:left;margin:8px 0;overflow-wrap:anywhere}.selected{background:#eaf1ff;border-color:#84a6e4}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.badge{background:#eaf0ff;color:#2458ae;padding:5px 9px;border-radius:14px;font-size:12px}.hint{background:#edf4ff;border:1px solid #cfdff5;border-radius:9px;padding:13px;font-size:13px;line-height:1.8}.notice{background:#fff8e9;border:1px solid #eadab8;padding:12px;border-radius:8px;font-size:12px;line-height:1.8}.empty{color:#75849a;padding:28px 12px;line-height:1.8}.bubble{margin:14px 0;padding:15px;border-radius:10px;background:#f3f6fa}.bubble.user{background:#edf3ff}.bubble.assistant{background:white;border:1px solid #dce5f0}.bubble pre{font:14px/1.8 Segoe UI,Microsoft YaHei,sans-serif;white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0}.source{font-size:11px;color:#6c7c90;line-height:1.7}.feedback{padding:12px;background:#f5f8fc;border-radius:8px;margin-top:10px}.record{border-top:1px solid #e5eaf1;padding:10px 0}.record summary{font-size:12px;cursor:pointer;overflow-wrap:anywhere}.record pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.6;max-height:240px;overflow:auto}.tiny{font-size:11px;padding:5px 8px}.count{font-size:25px;font-weight:600;color:#245dbd}#message{min-height:22px;font-size:13px;color:#245bb1}#message.error{color:#b42434}dialog{max-width:560px;width:92%;border:1px solid #cdd9e7;border-radius:12px;padding:24px}dialog::backdrop{background:#15273c88}input[type=checkbox]{width:auto;margin:0 6px 0 0}#thread{min-height:180px}.sample-form summary{font-size:14px;font-weight:600;cursor:pointer;margin-bottom:12px}#task-name{overflow-wrap:anywhere}@media(max-width:1150px){main{grid-template-columns:245px minmax(380px,1fr)}.memory{grid-column:1/-1}}@media(max-width:720px){main{display:block;padding:12px}header{display:block}nav{margin-top:12px}}
</style><header><div><h1>Autodidact / 示范学习</h1><p>教一组做法，让它处理新材料，再用你的反馈修订。</p></div><nav><span id="model-status" class="badge">检查模型配置…</span><button id="configure">连接模型</button><a href="/tools">文件与命令工具</a></nav></header>
<main><aside><section class="card"><h2>我要教它做什么</h2><label for="course-name">任务名称</label><input id="course-name" placeholder="例如：整理项目周报"><label for="course-instructions">任务要求（可选）</label><textarea id="course-instructions" rows="4" placeholder="例如：根据材料输出已完成、问题和下一步；不编造进度。"></textarea><button class="primary" id="create-course">创建这类任务</button></section><section class="card"><h2>我的任务</h2><div id="courses"></div></section><div class="notice">每类任务单独保存示范和反馈，原有研究知识库保持独立。回答不会自动变成已验证事实。</div></aside>
<section><div class="card"><div class="row" style="justify-content:space-between"><h2 id="task-name">从一个具体任务开始</h2><span id="progress" class="badge">选择任务</span></div><p id="task-instructions" class="muted"></p><div class="hint" id="guide">① 告诉它任务是什么　② 给一组输入和理想输出　③ 发新材料，让它照着做。<br>回答有偏差时直接反馈；你认可的答案可以成为下一次的示范。</div><p id="message" role="status"></p></div>
<details class="card sample-form" id="sample-form"><summary>给它一组示范</summary><label for="sample-input">示范输入 / 原始材料</label><textarea id="sample-input" rows="3" placeholder="粘贴一份实际任务材料"></textarea><label for="sample-output">你希望得到的理想输出</label><textarea id="sample-output" rows="4" placeholder="粘贴你认可的答案或处理结果"></textarea><button class="primary" id="save-sample" disabled>保存这组示范</button><span class="muted">只保存在本机，不调用模型。</span></details>
<section class="card"><h2>对话与结果</h2><div id="thread"><div class="empty">创建或选择一类任务后，就可以给示范、发新材料和纠正回答。</div></div><label for="new-input">让它试做新任务</label><textarea id="new-input" rows="4" placeholder="输入新的材料，或者继续这类任务的对话…"></textarea><div class="row"><button class="primary" id="send" disabled>发送新任务</button><button id="stop" hidden>停止生成</button></div><p class="muted">只在发送新任务或要求修订时调用模型；每轮最多4次生成，与本机工具共享UTC每日50次配额。</p></section></section>
<aside class="memory"><section class="card"><h2>这个任务已经记住的</h2><div class="row"><div><span class="count" id="sample-count">0</span><div class="muted">有效示范</div></div><div style="margin-left:30px"><span class="count" id="rule-count">0</span><div class="muted">通用要求</div></div></div><p class="muted">这些是你确认的任务资料。是否能处理好新材料，需要继续验证。</p><div id="samples"></div><div id="rules"></div></section><section class="card"><h2>它会怎样使用反馈</h2><p class="muted">认可回答 → 加入本任务示范。<br>指出偏差 → 根据反馈修订。<br>勾选通用要求 → 后续同类任务继续参考。<br>保存的示范和要求可以停用、恢复。</p><p class="notice">这里改变的是后续任务可使用的示范、要求和上下文，没有修改模型权重。重复示范输入也不能证明已泛化。</p></section></aside></main>
<dialog id="model-dialog"><h2>连接你的模型</h2><p class="muted">兼容 chat/completions 的模型服务。保存配置不会请求模型；发送任务后才会调用。Windows密钥加密保存在本机，不回显到页面。</p><label for="model-url">API基础地址</label><input id="model-url" placeholder="https://你的服务/v1"><label for="model-name">模型名称</label><input id="model-name" placeholder="填写服务商提供的模型ID"><label for="model-key">API密钥</label><input id="model-key" type="password" autocomplete="off" placeholder="首次填写；保存后不显示"><p id="model-error" class="error"></p><div class="row"><button class="primary" id="save-model">保存并启用</button><button id="close-model">关闭</button></div></dialog>
<script nonce="NONCE">
const token='TOKEN', $=id=>document.getElementById(id);
let selected=null,current=null,info=null,rendered='',busy=false;const drafts={};
const states={pending:'等待生成',generating:'正在生成',review:'等你反馈',accepted:'你已认可，已入示范',failed:'本次未完成',interrupted:'已停止 / 中断'};
async function api(path,data){const r=await fetch('/api/local/teaching'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Autodidact-Token':token},body:data===undefined?undefined:JSON.stringify(data)});const value=await r.json();if(!r.ok)throw Error(value.error||'请求未完成');return value;}
function message(text,error=false){$('message').textContent=text;$('message').className=error?'error':'';}
async function perform(action){try{await action();}catch(e){message(e.message,true);}finally{try{await refresh(true);}catch(e){message(e.message,true);}}}
function element(tag,text,cls=''){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;}
function modelDialog(){$('model-error').textContent='';$('model-url').value=info?.model.base_url||'';$('model-name').value=info?.model.model||'';$('model-key').value='';$('model-dialog').showModal();}
function showMemory(items,kind){const container=$(kind);container.replaceChildren();for(const item of items){const d=element('details',undefined,'record'),s=element('summary',(item.active?'':'已停用 · ')+(kind==='samples'?item.input.slice(0,60):item.text.slice(0,60)));d.append(s);d.append(element('pre',kind==='samples'?'输入：\n'+item.input+'\n\n理想输出：\n'+item.output:item.text));const b=element('button',item.active?'停用':'恢复','tiny');b.onclick=()=>perform(async()=>{await api('/courses/'+selected+'/'+kind+'/'+item.id,{active:!item.active});message('已更新这类任务的资料。');});d.append(b);container.append(d);}}
function feedbackBox(run){const box=element('div',undefined,'feedback'),controls=element('div',undefined,'row');const accept=element('button','认可，加入示范','good'),revise=element('button','需要调整');accept.disabled=busy;revise.disabled=busy;controls.append(accept,revise);box.append(controls);const form=element('div');form.hidden=true;const note=element('textarea');note.rows=3;note.placeholder='直接告诉它哪里不对、应该怎样处理';note.setAttribute('aria-label','修改反馈');const ideal=element('textarea');ideal.rows=3;ideal.placeholder='可选：给出这次的理想答案';ideal.setAttribute('aria-label','理想修订结果');const remember=element('input');remember.type='checkbox';const label=element('label','这条反馈是通用要求，后续同类任务也参考');label.prepend(remember);const submit=element('button','按反馈修订','primary');const draft=drafts[run.id]||{};note.value=draft.note||'';ideal.value=draft.ideal||'';remember.checked=!!draft.remember;form.hidden=!draft.open;const keep=()=>{drafts[run.id]={note:note.value,ideal:ideal.value,remember:remember.checked,open:!form.hidden};};note.oninput=keep;ideal.oninput=keep;remember.onchange=keep;form.append(note,ideal,label,element('br'),submit);box.append(form);revise.onclick=()=>{form.hidden=!form.hidden;keep();note.focus();};accept.onclick=()=>perform(async()=>{accept.disabled=true;await api('/runs/'+run.id+'/feedback',{action:'accept',version:run.versions.length,request_id:crypto.randomUUID()});message('已保存为这类任务的示范。下一条新任务会按相关性选用。');});submit.onclick=()=>perform(async()=>{submit.disabled=true;await api('/runs/'+run.id+'/feedback',{action:'revise',version:run.versions.length,note:note.value,ideal_output:ideal.value,remember:remember.checked,request_id:crypto.randomUUID()});delete drafts[run.id];message('正在根据你的反馈修订。');});return box;}
function render(detail){current=detail;$('task-name').textContent=detail.course.name;$('task-instructions').textContent=detail.course.instructions;$('sample-count').textContent=detail.samples.filter(s=>s.active).length;$('rule-count').textContent=detail.rules.filter(s=>s.active).length;$('progress').textContent=busy?'正在生成':'示范按任务保存';$('save-sample').disabled=false;$('send').disabled=busy;$('send').textContent=info?.model.ready?'发送新任务':'连接模型后试做';$('stop').hidden=!busy;showMemory(detail.samples,'samples');showMemory(detail.rules,'rules');if(!busy&&$('message').textContent.startsWith('正在')){const latest=detail.runs[0];message(latest?.status==='review'?'回答已生成，可以认可或提出修改。':latest?.status==='accepted'?'已保存为这类任务的示范。':latest?.error||'本轮生成已结束。',!!latest?.error);}
const thread=$('thread');thread.replaceChildren();if(!detail.runs.length){thread.append(element('div','示范保存后，在下方输入新的材料。回答出来后，你可以认可或指出需要调整的地方。','empty'));}
for(const run of [...detail.runs].reverse()){const user=element('div',undefined,'bubble user');user.append(element('strong','你 · 新任务'),element('pre',run.input));thread.append(user);for(const v of run.versions){const answer=element('div',undefined,'bubble assistant');answer.append(element('strong','Autodidact · 回答 '+v.version),element('pre',v.answer||(run.status==='generating'?'正在参考示范和要求生成…':run.error||'本次没有可用输出')));const used=v.used||{sample_ids:[],rule_ids:[],seen_input:false};answer.append(element('div',`本次参考 ${used.sample_ids.length} 条示范、${used.rule_ids.length} 条要求 · ${v.model}`+(used.seen_input?' · 输入与既有示范相同，此次不证明泛化':''),'source'));const correction=run.feedback.find(f=>f.request.action==='revise'&&f.request.version===v.version);if(correction)answer.append(element('pre','你的反馈：'+(correction.request.note||'')+(correction.request.ideal_output?'\n理想输出：'+correction.request.ideal_output:'')));thread.append(answer);}
const state=element('div',states[run.status]||run.status,'source');thread.append(state);if(run.status==='review')thread.append(feedbackBox(run));if(run.error&&run.status!=='generating')thread.append(element('div',run.error,'notice'));}}
async function refresh(force=false){info=await api('');busy=info.busy;$('model-status').textContent=info.model.ready?'模型已配置':'尚未连接模型';$('configure').textContent=info.model.ready?'模型配置':'连接模型';$('stop').hidden=!busy;$('send').disabled=!selected||busy;const courses=$('courses');courses.replaceChildren();for(const c of info.courses){const b=element('button',c.name,'course'+(selected===c.id?' selected':''));b.onclick=()=>perform(async()=>{selected=c.id;rendered='';message('');});courses.append(b);}if(selected){const c=info.courses.find(c=>c.id===selected);const signature=selected+':'+(c?.updated||c?.created)+':'+busy;if(force||rendered!==signature){render(await api('/courses/'+selected));rendered=signature;}}}
$('create-course').onclick=()=>perform(async()=>{const d=await api('/courses',{name:$('course-name').value,instructions:$('course-instructions').value});selected=d.course.id;rendered='';$('sample-form').open=true;message('已建立任务。给它一组你认可的输入和输出。');});
$('save-sample').onclick=()=>perform(async()=>{await api('/courses/'+selected+'/samples',{input:$('sample-input').value,output:$('sample-output').value});$('sample-input').value='';$('sample-output').value='';$('sample-form').open=false;message('示范已记住。现在可以发一份新材料，让它试做。');});
$('send').onclick=()=>perform(async()=>{if(!info?.model.ready){modelDialog();return;}$('send').disabled=true;await api('/courses/'+selected+'/runs',{input:$('new-input').value,request_id:crypto.randomUUID()});$('new-input').value='';message('正在生成；回答后可直接认可或给出修改反馈。');});
$('stop').onclick=()=>perform(async()=>{await api('/stop',{});message('已停止生成，示范和已收到的答案保留。');});
$('configure').onclick=modelDialog;$('close-model').onclick=()=>$('model-dialog').close();
$('save-model').onclick=async()=>{try{await api('/model',{base_url:$('model-url').value,model:$('model-name').value,api_key:$('model-key').value});$('model-key').value='';$('model-dialog').close();message('配置已保存；发送新任务时才会调用模型。');await refresh(true);}catch(e){$('model-error').textContent=e.message;}};
refresh().catch(e=>message(e.message,true));setInterval(()=>refresh().catch(e=>message(e.message,true)),2000);
</script></html>'''
